import mongoose from 'mongoose';
import { env } from '../config/env.js';
import { ART_STYLE_KEYS } from '../constants/artStyles.js';

/**
 * A piece of artwork prepared for minting: either generated by an AI image
 * provider or uploaded by the user, plus the (optionally AI-suggested)
 * metadata the user wants to mint with.
 *
 * Lifecycle: DRAFT -> (Phase 4) UPLOADED_TO_IPFS -> (Phase 6) MINTED.
 * FAILED is for AI image generation that did not complete.
 */
export const GENERATION_SOURCES = Object.freeze({ AI: 'AI', UPLOAD: 'UPLOAD' });
export const GENERATION_STATUS = Object.freeze({
  DRAFT: 'DRAFT',
  FAILED: 'FAILED',
  UPLOADED_TO_IPFS: 'UPLOADED_TO_IPFS',
  MINTED: 'MINTED',
});

const attributeSchema = new mongoose.Schema(
  {
    trait_type: { type: String, required: true, trim: true, maxlength: 40 },
    value: { type: String, required: true, trim: true, maxlength: 60 },
  },
  { _id: false }
);

/**
 * IPFS publishing progress. Each step's result is saved the moment it
 * succeeds, so a retry resumes from the failed step instead of re-uploading.
 *
 *   NOT_STARTED -> IN_PROGRESS -> IMAGE_UPLOADED -> COMPLETE
 *                       \______________\__________-> FAILED (retryable)
 */
export const IPFS_STATUS = Object.freeze({
  NOT_STARTED: 'NOT_STARTED',
  IN_PROGRESS: 'IN_PROGRESS',
  IMAGE_UPLOADED: 'IMAGE_UPLOADED',
  COMPLETE: 'COMPLETE',
  FAILED: 'FAILED',
});
export const IPFS_STEPS = Object.freeze({ IMAGE: 'IMAGE', METADATA: 'METADATA' });

const ipfsSchema = new mongoose.Schema(
  {
    status: { type: String, enum: Object.values(IPFS_STATUS), default: IPFS_STATUS.NOT_STARTED },

    imageCid: { type: String, default: null },
    imageFileId: { type: String, default: null }, // Pinata file id
    imageSha256: { type: String, default: null }, // fingerprint of the uploaded bytes
    imageUploadedAt: { type: Date, default: null },

    metadataCid: { type: String, default: null },
    metadataFileId: { type: String, default: null },
    metadataSha256: { type: String, default: null },
    metadata: { type: mongoose.Schema.Types.Mixed, default: null }, // exact JSON that was pinned
    metadataUploadedAt: { type: Date, default: null },

    failedStep: { type: String, enum: [...Object.values(IPFS_STEPS), null], default: null },
    lastError: { type: String, default: null },
    attempts: { type: Number, default: 0 },
    // Short lease so two requests (e.g. a double-click) can't publish at once.
    // Expires on its own if the server crashes mid-upload.
    lockedUntil: { type: Date, default: null },
  },
  { _id: false }
);

/**
 * Mint progress. The tx hash is saved as soon as the user's wallet sends it,
 * so a closed browser tab can't lose track of a mint; "Check status" resumes.
 */
export const MINT_PROGRESS = Object.freeze({
  NONE: 'NONE',
  PENDING: 'PENDING', // sent, waiting for confirmation / verification
  CONFIRMED: 'CONFIRMED',
  FAILED: 'FAILED', // reverted or failed verification; the user may mint again
});

const mintSchema = new mongoose.Schema(
  {
    status: { type: String, enum: Object.values(MINT_PROGRESS), default: MINT_PROGRESS.NONE },
    chainId: { type: Number, default: null },
    txHash: { type: String, lowercase: true, default: null },
    error: { type: String, default: null },
    submittedAt: { type: Date, default: null },
    confirmedAt: { type: Date, default: null },
  },
  { _id: false }
);

const ipfsUri = (cid) => (cid ? `ipfs://${cid}` : null);
const gatewayUrl = (cid) => (cid ? `${env.ipfs.gatewayUrl}/${cid}` : null);

const aiGenerationSchema = new mongoose.Schema(
  {
    user: { type: mongoose.Schema.Types.ObjectId, ref: 'User', required: true },
    source: { type: String, enum: Object.values(GENERATION_SOURCES), required: true },

    // What the user asked the AI for (optional for plain uploads).
    prompt: { type: String, trim: true, maxlength: 500, default: '' },
    style: { type: String, enum: ART_STYLE_KEYS, default: 'none' },

    // Public URL path of the stored image, e.g. /uploads/<uuid>.png
    generatedImage: { type: String, required: true },
    image: {
      fileName: { type: String, required: true },
      mimeType: { type: String, required: true },
      size: { type: Number, required: true },
      width: { type: Number, required: true },
      height: { type: Number, required: true },
    },

    // Metadata the user intends to mint with (editable; may come from AI suggestions).
    name: { type: String, trim: true, maxlength: 60, default: '' },
    description: { type: String, trim: true, maxlength: 1000, default: '' },
    collectionName: { type: String, trim: true, maxlength: 60, default: '' },
    attributes: { type: [attributeSchema], default: [] },
    aiSuggested: { type: Boolean, default: false },

    status: { type: String, enum: Object.values(GENERATION_STATUS), default: GENERATION_STATUS.DRAFT },

    ipfs: { type: ipfsSchema, default: () => ({}) },
    mint: { type: mintSchema, default: () => ({}) },
    nft: { type: mongoose.Schema.Types.ObjectId, ref: 'NFT', default: null },
  },
  { timestamps: true }
);

// "My artwork" list: newest first for one user.
aiGenerationSchema.index({ user: 1, createdAt: -1 });

aiGenerationSchema.set('toJSON', {
  transform(_doc, ret) {
    ret.id = ret._id.toString();
    delete ret._id;
    delete ret.__v;
    if (ret.ipfs) {
      ret.ipfs.imageUri = ipfsUri(ret.ipfs.imageCid);
      ret.ipfs.metadataUri = ipfsUri(ret.ipfs.metadataCid); // this becomes the NFT's tokenURI
      ret.ipfs.imageGatewayUrl = gatewayUrl(ret.ipfs.imageCid);
      ret.ipfs.metadataGatewayUrl = gatewayUrl(ret.ipfs.metadataCid);
      ret.ipfs.inProgress = Boolean(ret.ipfs.lockedUntil && new Date(ret.ipfs.lockedUntil) > new Date());
      delete ret.ipfs.lockedUntil;
    }
    return ret;
  },
});

export const AIGeneration = mongoose.model('AIGeneration', aiGenerationSchema);
